shell_commands.command:
cd /testbed && git apply --recount <<'PATCH'
diff --git a/tokio-util/tests/time_delay_queue.rs b/tokio-util/tests/time_delay_queue.rs
--- a/tokio-util/tests/time_delay_queue.rs
+++ b/tokio-util/tests/time_delay_queue.rs
@@ -171,6 +171,53 @@
     assert!(entry.is_none());
 }

+#[tokio::test(start_paused = true)]
+async fn remove_last_entry_wakes() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let deadline = Instant::now() + ms(100);
+    let key1 = queue.insert_at("foo", deadline);
+    let key2 = queue.insert_at("bar", deadline);
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.remove(&key1).into_inner(), "foo");
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.remove(&key2).into_inner(), "bar");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
+#[tokio::test(start_paused = true)]
+async fn try_remove_last_entry_wakes() {
+    let mut queue = task::spawn(DelayQueue::new());
+    let deadline = Instant::now() + ms(100);
+    let key1 = queue.insert_at("foo", deadline);
+    let key2 = queue.insert_at("bar", deadline);
+
+    assert_pending!(poll!(queue));
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.try_remove(&key1).unwrap().into_inner(), "foo");
+    assert!(!queue.is_woken());
+    assert!(queue.try_remove(&key1).is_none());
+    assert!(!queue.is_woken());
+
+    assert_eq!(queue.try_remove(&key2).unwrap().into_inner(), "bar");
+    assert!(queue.is_woken());
+    assert!(assert_ready!(poll!(queue)).is_none());
+}
+
 #[tokio::test]
 async fn reset_entry() {
     time::pause();
PATCH
cargo test --offline --test time_delay_queue --features full last_entry_wakes

